def pythagorean_triples(n):
    out = []
    for a in range(1, n + 1):
        for b in range(a + 1, n + 1):
            c2 = a * a + b * b
            c = int(c2 ** 0.5)
            if c <= n and c * c == c2:
                out.append([a, b, c])
    return out
